def group_existing_services(apps, schema_editor):
    db = schema_editor.connection.alias
    applications = apps.get_model("deployments", "Application").objects.using(db)
    if not applications.exists():
        return
    project = apps.get_model("deployments", "Project").objects.using(db).create(
        name="Default", slug="default",
    )
    env = apps.get_model("deployments", "Environment").objects.using(db).create(
        project=project, name="Production", slug="production",
    )
    connections = apps.get_model("deployments", "SourceConnection").objects.using(db)
    for app in applications.iterator():
        if app.repository:
            kind = "git"
            try:
                url = urlsplit(app.repository)
                host = url.netloc.lower() if url.scheme == "https" and not url.username else ""
            except ValueError:
                host = ""
        else:
            kind = "registry"
            head, slash, _ = app.image.partition("/")
            host = head.lower() if slash and ("." in head or ":" in head or head == "localhost") else "docker.io"
            if host in {"index.docker.io", "registry-1.docker.io"}:
                host = "docker.io"
        app.scope = env
        app.legacy_service_name = True
        if host:
            app.connection, _ = connections.get_or_create(
                name=host, kind=kind, defaults={"host": host},
            )
        app.save(using=db, update_fields=["scope", "legacy_service_name", "connection"])


